import java.util.Scanner;

public class MinCostCalculator {
    static long[] sequence = new long[18];

    static long minCost(long number, int position) {
        long count = number / sequence[position];
        if (number % sequence[position] == 0)
            return position * count;
        long costA = position * count + minCost(number % sequence[position], position - 1);
        long costB = position * (count + 1) + minCost(sequence[position] - (number % sequence[position]), position - 1);
        return Math.min(costA, costB);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        sequence[1] = 1;
        for (int i = 2; i <= 17; ++i) {
            sequence[i] = sequence[i - 1] * 10 + 1;
        }
        long n = scanner.nextLong();
        System.out.println(minCost(n, 17));
        scanner.close();
    }
}
